const NOTE_ATTACHMENT_BUCKET = "moonclean-service-attachments";
function PrivateAttachmentPreview({storeId,path,label,image}:{storeId:string|null;path:string;label:string;image:boolean}) {
 const [url,setUrl]=useState("");const [error,setError]=useState(false);
 const invalidPath=!storeId||!path.startsWith(`${storeId}/notes/`);
 useEffect(()=>{if(invalidPath)return;let cancelled=false;void createBrowserSupabaseClient().storage.from(NOTE_ATTACHMENT_BUCKET).createSignedUrl(path,3600).then(({data,error:storageError})=>{if(cancelled)return;if(storageError)throw storageError;setUrl(data.signedUrl);}).catch(()=>{if(!cancelled)setError(true);});return()=>{cancelled=true;};},[invalidPath,path]);
 if(invalidPath||error)return <span className="text-xs text-[var(--mc-color-danger)]">附件无法读取：{label}</span>;
 if(!url)return <span className="inline-flex items-center gap-1 text-xs text-muted-foreground"><LoaderCircle size={13} className="animate-spin"/>正在加载附件…</span>;
 return image?<a href={url} target="_blank" rel="noreferrer" className="my-2 block max-w-full"><Image src={url} alt={label} width={960} height={640} unoptimized className="max-h-96 w-auto rounded-xl border border-border object-contain"/></a>:<a href={url} target="_blank" rel="noreferrer" className="my-2 inline-flex items-center gap-2 rounded-xl border border-border bg-[var(--mc-tint-blue)] px-3 py-2 text-xs font-medium text-primary"><FilePlus2 size={14}/>{label}<Upload size={12}/></a>;
}
function MarkdownReply({content,storeId=null,allowAttachments=false}:{content:string;storeId?:string|null;allowAttachments?:boolean}) {
 const inline=(value:string)=>value.split(/(\*\*[^*]+\*\*)/g).map((part,index)=>part.startsWith("**")&&part.endsWith("**")?<strong key={index}>{part.slice(2,-2)}</strong>:part);
 return <div className="space-y-1.5 text-sm leading-6">{content.split("\n").map((line,index)=>{
   const value=line.trim();if(!value)return <div key={index} className="h-1"/>;
   const attachment=allowAttachments?parsePrivateAttachmentMarkdown(value):null;
   if(attachment)return <PrivateAttachmentPreview key={index} storeId={storeId} {...attachment}/>;
   if(value.startsWith("### "))return <h4 key={index} className="pt-1 font-semibold">{inline(value.slice(4))}</h4>;
   if(value.startsWith("## "))return <h3 key={index} className="pt-1 text-base font-semibold">{inline(value.slice(3))}</h3>;
   if(value.startsWith("# "))return <h2 key={index} className="pt-1 text-lg font-bold">{inline(value.slice(2))}</h2>;
   if(value.startsWith("> "))return <blockquote key={index} className="border-l-2 border-border pl-3 text-muted-foreground">{inline(value.slice(2))}</blockquote>;
   if(/^[-*] /.test(value))return <p key={index} className="pl-3 before:mr-2 before:text-primary before:content-['•']">{inline(value.slice(2))}</p>;
   if(/^\d+[.)] /.test(value))return <p key={index} className="pl-3">{inline(value)}</p>;
   if(value.startsWith("|")&&value.endsWith("|")){const cells=value.split("|").slice(1,-1).map(cell=>cell.trim());if(cells.every(cell=>/^:?-{2,}:?$/.test(cell)))return null;return <div key={index} className="grid grid-cols-2 gap-px overflow-hidden rounded-md bg-[var(--mc-tint-blue)] text-xs">{cells.map((cell,cellIndex)=><span key={cellIndex} className="bg-[var(--mc-tint-blue)] px-2 py-1.5">{inline(cell)}</span>)}</div>;}
   return <p key={index}>{inline(value)}</p>;
 })}</div>;
}
function useRows(resource:WorkspaceResource,feature:WorkspaceFeature){ return useWorkspaceResource(resource,feature); }
function useMutationFeedback() { return useCallback((cause:unknown,action:string)=>notifyFeedback({kind:"error",title:action,description:cause instanceof Error?cause.message:"请检查网络后重试"}),[]); }
async function createWorkspaceTask(input:{storeId:string|null;mode:"cloud"|"local";update:(fn:(data:AppData)=>AppData)=>Promise<void>;title:string;detail:string;sourceModule?:"notes"|"experiments"|"competitors"|"service-cases"|"copilot-conversations";sourceId?:string}) {
 if(!input.storeId)throw new Error("请先选择店铺");
 const task={title:input.title.slice(0,160),detail:input.detail.slice(0,1000),priority:"normal" as const,status:"todo" as const,dueDate:null,sourceModule:input.sourceModule||null,sourceId:input.sourceId||null};
 if(input.mode==="cloud") await operationsRequest(input.storeId,"tasks",task,"POST");
 else await input.update(current=>({...current,tasks:[{...task,source_module:task.sourceModule,source_id:task.sourceId,id:crypto.randomUUID(),due_date:null,created_at:new Date().toISOString(),updated_at:new Date().toISOString()},...(current.tasks||[])]}));
 if(input.mode==="local")notifyFeedback({kind:"success",title:"已添加到运营待办",description:"任务已保存在本机数据中。"});
}

function NotesModule({initialNoteId=""}:{initialNoteId?:string}){
 const router=useRouter();const {mode,activeStoreId,data,update,role}=useApp(); const {rows,loading,error,refresh,create,update:save,remove,restore,archive:archiveRow,unarchive}=useRows("notes","notes"); const versions=useRows("note-versions","notes");const experiments=useRows("experiments","notes");const competitors=useRows("competitors","notes");const cases=useRows("service-cases","notes");const conversations=useRows("copilot-conversations","notes"); const report=useMutationFeedback();
 const [selected,setSelected]=useState("");const [search,setSearch]=useState("");const [filter,setFilter]=useState("active");const [title,setTitle]=useState("");const [body,setBody]=useState("");const [category,setCategory]=useState("运营复盘");const [folder,setFolder]=useState("");const [tags,setTags]=useState("");const [relatedType,setRelatedType]=useState("");const [relatedId,setRelatedId]=useState("");const [saveStatus,setSaveStatus]=useState("已同步");const [busy,setBusy]=useState(false);const [uploading,setUploading]=useState(false);const [uploadError,setUploadError]=useState("");const [isNew,setIsNew]=useState(false);const [previewMode,setPreviewMode]=useState(false);const editor=useRef<HTMLTextAreaElement>(null);const attachmentInput=useRef<HTMLInputElement>(null); const canEdit=mode==="local"||role!=="viewer";
 const visible=useMemo(()=>rows.filter(row=>{const deleted=Boolean(row.deleted_at);const archived=Boolean(row.archived_at);return (filter==="trash"?deleted:filter==="archive"?archived:filter==="favorites"?!deleted&&!archived&&Boolean(row.is_favorite):!deleted&&!archived)&&`${row.title} ${row.body_markdown} ${row.category} ${(row.tags as string[]||[]).join(" ")}`.toLowerCase().includes(search.toLowerCase());}).sort((a,b)=>Number(Boolean(b.is_pinned))-Number(Boolean(a.is_pinned))||String(b.updated_at||b.created_at).localeCompare(String(a.updated_at||a.created_at))),[rows,search,filter]);
 const current=rows.find(row=>row.id===selected);
 const relatedOptions=relatedType==="product"?(data?.products||[]).map(p=>({id:p.id,label:p.name})):relatedType==="sku"?(data?.products||[]).flatMap(p=>p.skus.map(s=>({id:s.id,label:`${p.name} · ${s.name}`}))):relatedType==="experiment"?experiments.rows.map(r=>({id:r.id,label:String(r.name)})):relatedType==="competitor"?competitors.rows.map(r=>({id:r.id,label:String(r.product_name)})):relatedType==="service_case"?cases.rows.map(r=>({id:r.id,label:`${String(r.order_number||"售后工单")} · ${String(r.issue_category)}`})):relatedType==="copilot_conversation"?conversations.rows.map(r=>({id:r.id,label:String(r.title)})):[];
 const draftKey=useCallback((id:string)=>`moonclean-notes-draft-v1:${activeStoreId}:${id}`,[activeStoreId]);
 const selectNote=useCallback((row:WorkspaceRow)=>{let next={title:String(row.title),body:String(row.body_markdown||""),category:String(row.category),folder:String(row.folder||""),tags:(row.tags as string[]||[]).join(", "),relatedType:String(row.related_type||""),relatedId:String(row.related_id||"")};try{const saved=localStorage.getItem(draftKey(row.id));if(saved&&window.confirm("发现这条笔记尚未同步的本机草稿，要恢复吗？")){next={...next,...JSON.parse(saved) as typeof next};}}catch{/* Ignore damaged device drafts. */}setSelected(row.id);setTitle(next.title);setBody(next.body);setCategory(next.category);setFolder(next.folder);setTags(next.tags);setRelatedType(next.relatedType);setRelatedId(next.relatedId);setIsNew(false);setPreviewMode(false);},[draftKey]);
 const autoOpened=useRef(false);useEffect(()=>{if(!initialNoteId||autoOpened.current)return;const row=rows.find(item=>item.id===initialNoteId);if(!row)return;const timer=window.setTimeout(()=>{if(!autoOpened.current){selectNote(row);autoOpened.current=true;}},0);return()=>window.clearTimeout(timer);},[initialNoteId,rows,selectNote]);
 useEffect(()=>{if(!activeStoreId||(!selected&&!isNew))return;const key=`moonclean-notes-draft-v1:${activeStoreId}:${selected||"new"}`;const timer=window.setTimeout(()=>{try{localStorage.setItem(key,JSON.stringify({title,body,category,folder,tags,relatedType,relatedId,savedAt:new Date().toISOString()}));}catch{/* Keep editing even when local storage is unavailable. */}},250);return()=>window.clearTimeout(timer);},[activeStoreId,selected,isNew,title,body,category,folder,tags,relatedType,relatedId]);
 const archiveNote=async()=>{if(!current)return;try{await archiveRow(current.id);setSelected("");}catch(e){report(e,"归档失败");}};
 const createExperimentFromNote=async()=>{if(!current)return;try{await experiments.create({name:`验证笔记方案：${current.title}`,experiment_type:"custom",status:"draft",test_design:"before_after",source_note_id:current.id,hypothesis:String(current.body_markdown||"").slice(0,3900)});router.push("/experiments");}catch(e){report(e,"从笔记创建实验失败");}};
 const associationInvalid=Boolean(relatedType)!==Boolean(relatedId);
 const saveNote=useCallback(async()=>{if(!canEdit||(!title.trim()&&!body.trim()))return;if(Boolean(relatedType)!==Boolean(relatedId)){setSaveStatus("请选择关联记录，或将关联类型设为不关联。");return;}setBusy(true);setSaveStatus("正在保存…");try{const payload={title:title.trim()||"未命名笔记",body_markdown:body,category,tags:tags.split(/[，,]/).map(s=>s.trim()).filter(Boolean),folder,related_type:relatedType||null,related_id:relatedId||null};if(current){await save({id:current.id,...payload});}else{const row=await create(payload);setIsNew(false);await refresh();if(row&&typeof row==="object"&&"id" in row)setSelected(String((row as {id:string}).id));}try{localStorage.removeItem(draftKey(selected||"new"));}catch{/* Cloud/local save already succeeded. */}setSaveStatus("已保存");}catch(e){setSaveStatus("保存失败");report(e,"保存笔记失败");}finally{setBusy(false);}},[canEdit,title,body,category,tags,folder,relatedType,relatedId,current,save,create,refresh,draftKey,selected,report]);
 const saveLatest=useRef(saveNote);useEffect(()=>{saveLatest.current=saveNote;},[saveNote]);
 useEffect(()=>{if(!selected||!canEdit||Boolean(relatedType)!==Boolean(relatedId))return;const timer=window.setTimeout(()=>void saveLatest.current(),900);return()=>window.clearTimeout(timer);},[selected,canEdit,title,body,category,folder,tags,relatedType,relatedId]);
 const insert=(before:string,after="")=>{const el=editor.current;if(!el)return;const a=el.selectionStart,b=el.selectionEnd,selection=body.slice(a,b)||"文字";const next=body.slice(0,a)+before+selection+after+body.slice(b);setBody(next);requestAnimationFrame(()=>{el.focus();el.setSelectionRange(a+before.length,a+before.length+selection.length);});};
 const uploadNoteAttachment=async(file:File)=>{if(mode!=="cloud"||!activeStoreId){setUploadError("附件上传需要已登录的云端店铺。");return;}const extensions:Record<string,string>={"image/jpeg":"jpg","image/png":"png","image/webp":"webp","application/pdf":"pdf"};const ext=extensions[file.type];if(!ext||file.size>10*1024*1024){setUploadError("仅支持 JPG、PNG、WebP 或 PDF，单个文件最大 10MB。");return;}setUploading(true);setUploadError("");try{const path=`${activeStoreId}/notes/${selected||"draft"}/${crypto.randomUUID()}.${ext}`;const {error}=await createBrowserSupabaseClient().storage.from(NOTE_ATTACHMENT_BUCKET).upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;const markdown=privateAttachmentMarkdown(file.name,path,file.type.startsWith("image/"));setBody(current=>`${current.trimEnd()}${current.trim()?"\n\n":""}${markdown}\n`);notifyFeedback({kind:"success",title:"附件已上传",description:"附件保存在当前店铺的私有存储，并已插入笔记。"});}catch(cause){const message=cause instanceof Error?cause.message:"上传失败，请重试。";setUploadError(message);report(cause,"笔记附件上传失败");}finally{setUploading(false);if(attachmentInput.current)attachmentInput.current.value="";}};
 const createTask=async()=>{if(!current||!activeStoreId)return;try{const task={title:`跟进：${current.title}`,detail:body.slice(0,900),priority:"normal" as const,status:"todo" as const,dueDate:null,sourceModule:"notes" as const,sourceId:current.id};if(mode==="cloud")await operationsRequest(activeStoreId,"tasks",task,"POST");else await update(d=>({...d,tasks:[{...task,source_module:task.sourceModule,source_id:task.sourceId,id:crypto.randomUUID(),due_date:null,created_at:new Date().toISOString(),updated_at:new Date().toISOString()},...(d.tasks||[])]}));notifyFeedback({kind:"success",title:"已转为运营待办",description:"可在运营待办页面跟进处理，并从任务返回来源笔记。"});}catch(e){report(e,"转为任务失败");}};
 const clone=async()=>{if(!current)return;try{const row=await create({title:`${current.title}（副本）`,body_markdown:current.body_markdown,category:current.category,tags:current.tags||[]});if(row&&"id"in(row as object))setSelected(String((row as {id:string}).id));}catch(e){report(e,"复制失败");}};
 return <>
 <PageHead eyebrow={meta.notes.eyebrow} title={meta.notes.title} description={meta.notes.description} action={<Button disabled={!canEdit} onClick={()=>{setSelected("");setTitle("");setBody("");setCategory("运营复盘");setFolder("");setTags("");setRelatedType("");setRelatedId("");setIsNew(true);setPreviewMode(false);try{const saved=localStorage.getItem(draftKey("new"));if(saved&&window.confirm("发现尚未保存的本机草稿，要恢复吗？")){const draft=JSON.parse(saved);setTitle(draft.title||"");setBody(draft.body||"");setCategory(draft.category||"运营复盘");setFolder(draft.folder||"");setTags(draft.tags||"");}}catch{/* Ignore damaged drafts. */}}}><Plus size={16}/>新建笔记</Button>}/>
 <div className="grid gap-4 xl:grid-cols-[210px_minmax(250px,340px)_minmax(0,1fr)]">
  <Panel className="hidden xl:block"><p className="mb-3 text-sm font-semibold">笔记分类</p>{[["active","全部笔记"],["favorites","我的收藏"],["archive","归档"],["trash","回收站"]].map(([id,label])=><button key={id} onClick={()=>setFilter(id)} className={`mb-1 w-full rounded-xl px-3 py-2.5 text-left text-sm ${filter===id?"bg-[var(--mc-tint-blue)] font-semibold text-primary":"text-muted-foreground hover:bg-[var(--mc-tint-blue)]"}`}>{label}{id==="active"&&<span className="float-right">{rows.filter(r=>!r.deleted_at&&!r.archived_at).length}</span>}</button>)}<div className="mt-5 border-t border-border pt-4"><p className="mb-2 text-xs font-semibold text-muted-foreground">常用分类</p>{[...new Set(rows.map(r=>String(r.category)))].map(c=><button key={c} onClick={()=>{setFilter("active");setSearch(c);}} className="mb-1 block text-left text-xs text-muted-foreground">{c}</button>)}</div></Panel>
  <Panel className={`${selected||isNew?"hidden":"block"} xl:block`}><AppSelect aria-label="笔记视图" value={filter} onChange={e=>setFilter(e.target.value)} className="mb-2 h-9 w-full rounded-xl border border-border bg-card px-3 text-xs xl:hidden"><option value="active">全部笔记</option><option value="favorites">我的收藏</option><option value="archive">归档</option><option value="trash">回收站</option></AppSelect><div className="relative mb-3"><Search className="absolute left-3 top-3 text-muted-foreground" size={15}/><Input aria-label="搜索备忘录" value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索标题、正文、标签" className="pl-9"/></div>{loading?<p className="py-8 text-center text-sm text-muted-foreground">正在加载笔记…</p>:error?<div className="text-sm text-[var(--mc-color-danger)]">{error}<Button size="sm" variant="outline" onClick={()=>void refresh()}>重试</Button></div>:visible.length===0?<Empty title="暂无匹配笔记" detail="调整搜索条件，或创建一条新的运营备忘录。"/>:<div className="max-h-[70vh] space-y-2 overflow-y-auto">{visible.map(row=><button key={row.id} onClick={()=>selectNote(row)} className={`w-full rounded-2xl border p-3 text-left ${selected===row.id?"border-border bg-[var(--mc-tint-blue)]":"border-border hover:bg-[var(--mc-tint-blue)]"}`}><div className="flex items-center gap-2 text-sm font-semibold text-foreground">{Boolean(row.is_pinned)&&<span title="置顶">📌</span>}{Boolean(row.is_favorite)&&<Star size={13} className="fill-[#f4b942] text-[var(--mc-color-warning)]"/>}<span className="truncate">{String(row.title)}</span></div><p className="mt-1 line-clamp-2 text-xs leading-5 text-muted-foreground">{String(row.body_markdown||"")}</p><p className="mt-2 text-[10px] text-muted-foreground">{String(row.category)} · {new Date(String(row.updated_at||row.created_at)).toLocaleDateString("zh-CN")}</p></button>)}</div>}</Panel>
  <Panel className={`${selected||isNew?"block":"hidden"} xl:block`}><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs text-muted-foreground">{current||isNew?"编辑器":"选择一条笔记"} · {saveStatus}</p>{current&&<p className="mt-1 text-[10px] text-muted-foreground">自动保存 · {mode==="cloud"?"云端版本历史":"本机持久化"}</p>}</div>{current&&<div className="flex items-center gap-1"><Button size="icon-sm" variant="ghost" title={current.is_favorite?"取消收藏":"收藏笔记"} onClick={()=>void save({id:current.id,is_favorite:!current.is_favorite})}><Star size={15} className={current.is_favorite?"fill-[#f4b942] text-[var(--mc-color-warning)]":""}/></Button><Button size="icon-sm" variant="ghost" title={current.is_pinned?"取消置顶":"置顶笔记"} onClick={()=>void save({id:current.id,is_pinned:!current.is_pinned})}>{current.is_pinned?"📌":"⌖"}</Button><details className="relative"><summary className="flex h-9 cursor-pointer list-none items-center gap-1 rounded-xl border border-border bg-card px-3 text-xs text-muted-foreground">更多操作<ChevronDown size={14}/></summary><div className="absolute right-0 top-10 z-20 grid min-w-40 gap-1 rounded-xl border border-border bg-card p-2 shadow-lg"><Button size="sm" variant="ghost" onClick={()=>void createTask()}><Check size={14}/>转为任务</Button><Button size="sm" variant="ghost" onClick={()=>void createExperimentFromNote()}><FlaskConical size={14}/>创建实验</Button><Button size="sm" variant="ghost" onClick={()=>void clone()}><Copy size={14}/>复制笔记</Button><Button size="sm" variant="ghost" onClick={()=>void versions.refresh()}><History size={14}/>刷新版本记录</Button>{filter==="trash"?<Button size="sm" variant="ghost" onClick={()=>void restore(current.id)}><RotateCcw size={14}/>恢复</Button>:filter==="archive"?<Button size="sm" variant="ghost" onClick={()=>void unarchive(current.id)}><RotateCcw size={14}/>取消归档</Button>:<><Button size="sm" variant="ghost" onClick={()=>void archiveNote()}><Archive size={14}/>归档</Button><Button size="sm" variant="ghost" onClick={()=>void remove(current.id)}><Trash2 size={14}/>移入回收站</Button></>}</div></details></div>}</div>{current||isNew?<div className="space-y-3"><Input aria-label="笔记标题" maxLength={240} value={title} onChange={e=>setTitle(e.target.value)} placeholder="给这条笔记起个标题" className="h-12 border-0 px-0 text-xl font-bold shadow-none focus-visible:ring-0" disabled={!canEdit}/><div className="grid gap-2 sm:grid-cols-2"><Field label="分类"><Input value={category} maxLength={80} onChange={e=>setCategory(e.target.value)} placeholder="运营复盘" disabled={!canEdit}/></Field><Field label="文件夹"><Input value={folder} maxLength={80} onChange={e=>setFolder(e.target.value)} placeholder="例如：双十一活动" disabled={!canEdit}/></Field><Field label="标签（逗号分隔）"><Input value={tags} onChange={e=>setTags(e.target.value)} placeholder="活动, 主图" disabled={!canEdit}/></Field></div><div className="rounded-xl border border-border bg-[var(--mc-tint-blue)]/40 p-2"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex flex-wrap gap-1">{[["标题","## ",""],["粗体","**","**"],["列表","\n- ",""],["引用","\n> ",""]].map(([label,b,a])=><Button key={label} size="xs" variant="outline" disabled={!canEdit||previewMode} onClick={()=>insert(b,a)}>{label}</Button>)}<details className="relative"><summary className="flex h-8 cursor-pointer list-none items-center gap-1 rounded-lg border border-border bg-card px-2 text-[11px] text-muted-foreground">更多格式<ChevronDown size={13}/></summary><div className="absolute left-0 top-9 z-10 grid min-w-36 gap-1 rounded-xl border border-border bg-card p-2 shadow-lg">{[["待办","\n- [ ] ",""],["链接","[","](https://)"],["图片","![图片说明](","https://图片地址)"],["表格","\n| 项目 | 记录 |\n| --- | --- |\n|  |  |\n",""]].map(([label,b,a])=><Button key={label} size="xs" variant="ghost" disabled={!canEdit||previewMode} onClick={()=>insert(b,a)}>{label}</Button>)}</div></details><Button type="button" size="xs" variant="outline" title="上传图片或文件" disabled={!canEdit||mode!=="cloud"||uploading||previewMode} onClick={()=>attachmentInput.current?.click()}>{uploading?<LoaderCircle size={13} className="animate-spin"/>:<ImagePlus size={13}/>}<span>上传</span></Button><input ref={attachmentInput} type="file" accept="image/jpeg,image/png,image/webp,application/pdf" className="hidden" onChange={e=>{const file=e.target.files?.[0];if(file)void uploadNoteAttachment(file);}}/></div><div className="flex items-center gap-2"><span className="text-[10px] text-muted-foreground">{body.length} 字</span><Button type="button" size="xs" variant={previewMode?"default":"outline"} onClick={()=>setPreviewMode(!previewMode)}>{previewMode?"继续编辑":"预览"}</Button></div></div></div>{uploadError&&<p role="alert" className="rounded-xl bg-[var(--mc-tint-red)] px-3 py-2 text-xs text-[var(--mc-color-danger)]">{uploadError}</p>}{mode!=="cloud"&&<p className="text-[10px] text-muted-foreground">附件上传仅适用于云端店铺，支持 JPG、PNG、WebP、PDF，单个文件不超过 10 MB。</p>}{previewMode?<div className="min-h-[360px] rounded-2xl border border-border bg-card p-4 sm:p-6"><MarkdownReply content={body||"还没有正文内容。"} storeId={activeStoreId} allowAttachments/></div>:<Textarea ref={editor} aria-label="Markdown 笔记正文" value={body} onChange={e=>setBody(e.target.value)} className="min-h-[360px] resize-y rounded-2xl border-border p-4 leading-7" placeholder="记录经营判断、活动复盘、下一步动作……支持 Markdown 标题、列表、待办、表格、引用和链接。" disabled={!canEdit}/>}<AiNoteTools key={selected||"new"} storeId={activeStoreId} enabled={mode==="cloud"&&Boolean(activeStoreId)&&canEdit} title={title} content={body} onApply={(action,result)=>{setBody(current=>applyAiNoteContent(action,current,result));setPreviewMode(true);}}/>
 <div className="grid gap-2 sm:grid-cols-2"><Field label="关联类型"><AppSelect value={relatedType} onChange={e=>{setRelatedType(e.target.value);setRelatedId("");}} className={fieldClass}><option value="">不关联</option><option value="product">商品</option><option value="sku">SKU</option><option value="experiment">运营实验</option><option value="competitor">竞品</option><option value="service_case">售后案例</option><option value="copilot_conversation">AI 分析会话</option></AppSelect></Field><Field label="关联记录"><AppSelect value={relatedId} onChange={e=>setRelatedId(e.target.value)} className={fieldClass} disabled={!relatedType||!canEdit}><option value="">请选择记录</option>{relatedOptions.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</AppSelect></Field></div>{Boolean(current?.related_type&&current.related_id)&&<Button size="xs" variant="outline" onClick={()=>{if(!current)return;const href=current.related_type==="product"||current.related_type==="sku"?"/products":current.related_type==="experiment"?"/experiments":current.related_type==="competitor"?"/competitors":current.related_type==="service_case"?"/service":current.related_type==="copilot_conversation"?"/copilot":"/notes";const key=current.related_type==="copilot_conversation"?"conversation":"id";router.push(`${href}?${key}=${current.related_id}`);}}>查看关联业务记录</Button>}<div>{associationInvalid&&<p role="alert" className="mb-2 text-xs text-[var(--mc-color-danger)]">请选择关联记录，或将关联类型设为“不关联”。</p>}<div className="flex justify-end gap-2"><Button variant="outline" onClick={()=>{setIsNew(false);setSelected("");}}>关闭</Button><Button onClick={()=>void saveNote()} disabled={!canEdit||busy||associationInvalid||(!title.trim()&&!body.trim())}>{busy?"保存中…":"保存笔记"}</Button></div></div>{versions.rows.filter(v=>v.note_id===current?.id).length>0&&<details className="rounded-xl bg-[var(--mc-tint-blue)] p-3 text-xs"><summary className="cursor-pointer font-semibold">历史版本（{versions.rows.filter(v=>v.note_id===current?.id).length}）</summary><div className="mt-2 space-y-2">{versions.rows.filter(v=>v.note_id===current?.id).map(v=><div key={v.id} className="border-t border-border pt-2"><b>版本 {String(v.version_number)}</b> · {new Date(String(v.created_at)).toLocaleString("zh-CN")}<p className="mt-1 line-clamp-2 text-muted-foreground">{String(v.title)} — {String(v.body_markdown)}</p><Button size="xs" variant="outline" onClick={()=>{setTitle(String(v.title));setBody(String(v.body_markdown));}}>恢复此版本</Button></div>)}</div></details>}</div>:<Empty title="从左侧选择笔记" detail="也可以新建备忘录，内容会自动保存并保留历史版本。"/>}</Panel>
 </div></>;
}

function ExperimentsModule({initialRecordId=""}:{initialRecordId?:string}){
  const { data, mode, activeStoreId, update } = useApp();
  const router = useRouter();
  const exp = useRows("experiments","experiments");
  const notes = useRows("notes","notes");
  const [editing, setEditing] = useState<WorkspaceRow | null>(null);
  const [search, setSearch] = useState("");
  const report = useMutationFeedback();
  const [form,setForm] = useState(blankExperimentForm);
  const statusNames:Record<string,string>={draft:"草稿",planned:"待开始",running:"进行中",paused:"暂停",completed:"完成",cancelled:"已取消"};
  const productName=(id:string)=>data?.products.find(p=>p.id===id)?.name||"未关联商品";
  const open=useCallback((row?:WorkspaceRow)=>{
    setEditing(row||null);
    if(!row){setForm(blankExperimentForm);return;}
    setForm(Object.fromEntries(Object.keys(blankExperimentForm).map(key=>{const value=row[key];return [key,value&&typeof value==="object"?JSON.stringify(value):String(value??"")];})) as typeof blankExperimentForm);
  },[]);
  const openedId=useRef("");
  useEffect(()=>{if(!initialRecordId||openedId.current===initialRecordId)return;const row=exp.rows.find(item=>item.id===initialRecordId);if(!row)return;const timer=window.setTimeout(()=>{open(row);openedId.current=initialRecordId;},0);return()=>window.clearTimeout(timer);},[initialRecordId,exp.rows,open]);
  const save=async(e:React.FormEvent)=>{
    e.preventDefault();
    try {
      const baseline=JSON.parse(form.baseline_metrics||"{}");const result=JSON.parse(form.result_metrics||"{}");
      const payload={...form,product_id:form.product_id||null,source_note_id:form.source_note_id||null,start_date:form.start_date||null,end_date:form.end_date||null,baseline_metrics:baseline,result_metrics:result};
      if(editing)await exp.update({id:editing.id,...payload});else await exp.create(payload);
      setEditing(null);setForm(blankExperimentForm);
    } catch(error){report(error,"实验保存失败，请检查日期和指标 JSON 格式");}
  };
  const delta=(before:number,after:number)=>({absolute:after-before,relative:before===0?null:(after-before)/Math.abs(before)*100});
  const createNote=async(row:WorkspaceRow)=>{
    try { await notes.create({title:`实验复盘：${row.name}`,category:"实验经验",body_markdown:`## 实验结果\n\n${row.conclusion||"待总结"}\n\n## 下一步\n\n${row.next_steps||"待填写"}\n\n> ${row.test_design==="randomized_ab"?"随机 A/B 测试":"前后对比，不代表因果"}`,related_type:"experiment",related_id:row.id});notifyFeedback({kind:"success",title:"实验经验已归档到备忘录"}); }
    catch(error){report(error,"归档实验失败");}
  };
  return <>
    <PageHead eyebrow={meta.experiments.eyebrow} title={meta.experiments.title} description={meta.experiments.description} action={<Button onClick={()=>open()}><Plus size={16}/>新建实验</Button>}/>
    <div className="grid gap-4 xl:grid-cols-[minmax(0,1.3fr)_minmax(320px,.7fr)]">
      <SectionCard title="实验记录" sub="前后对比只表示同期变化，不证明策略因果" action={<div className="relative"><Search size={14} className="absolute left-3 top-3 text-muted-foreground"/><Input value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索实验" className="pl-8"/></div>}>
        {exp.loading?<p className="text-sm text-muted-foreground">正在读取实验…</p>:exp.error?<p role="alert" className="text-sm text-[var(--mc-color-danger)]">{exp.error}<Button size="sm" onClick={()=>void exp.refresh()}>重试</Button></p>:exp.rows.filter(row=>`${row.name} ${row.hypothesis}`.toLowerCase().includes(search.toLowerCase())).length===0?<Empty title="还没有实验" detail="从主图、标题、价格或推广策略开始记录一次实验。"/>:<div className="space-y-3">{exp.rows.filter(row=>`${row.name} ${row.hypothesis}`.toLowerCase().includes(search.toLowerCase())).map(row=>{
          const baseline=(row.baseline_metrics||{}) as Record<string,number>;const result=(row.result_metrics||{}) as Record<string,number>;
          return <article key={row.id} className="rounded-2xl border border-border p-4">
            <div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="font-semibold">{String(row.name)}</h3><p className="mt-1 text-xs text-muted-foreground">{productName(String(row.product_id||""))} · {row.test_design==="randomized_ab"?"随机 A/B 测试":"普通前后对比"} · {statusNames[String(row.status)]||String(row.status)}</p></div><div className="flex flex-wrap gap-1"><Button size="sm" variant="outline" onClick={()=>open(row)}>编辑 / 记录结果</Button>{Boolean(row.source_note_id)&&<Button size="sm" variant="outline" onClick={()=>router.push(`/notes?id=${String(row.source_note_id)}`)}>查看来源笔记</Button>}</div></div>
            <p className="mt-3 text-sm leading-6 text-muted-foreground">假设：{String(row.hypothesis||"尚未填写")}</p>
            {Object.keys(result).length>0&&<div className="mt-3 grid grid-cols-2 gap-2 md:grid-cols-4">{Object.keys(result).map(key=>{const change=delta(Number(baseline[key]||0),Number(result[key]));return <div key={key} className="rounded-xl bg-[var(--mc-tint-blue)] p-2.5"><p className="text-[10px] text-muted-foreground">{key}</p><p className="number text-sm font-semibold">{Number(baseline[key]||0)} → {result[key]}</p><p className="text-[10px] text-primary">变化 {change.absolute>0?"+":""}{change.absolute}{change.relative===null?"":"（"+(change.relative>0?"+":"")+change.relative.toFixed(1)+"%）"}</p></div>;})}</div>}
            {Boolean(row.conclusion)&&<p className="mt-3 rounded-xl bg-[var(--mc-tint-blue)] p-3 text-xs leading-5">总结：{String(row.conclusion)}</p>}
            <div className="mt-3 flex flex-wrap gap-2"><Button size="xs" variant="outline" onClick={()=>void createNote(row)}>归档到备忘录</Button><Button size="xs" variant="outline" onClick={()=>void createWorkspaceTask({storeId:activeStoreId,mode,update,title:`复盘运营实验：${String(row.name)}`,detail:`实验状态：${String(row.status)}。假设：${String(row.hypothesis||"未填写")}。结果：${JSON.stringify(result)}。请复核指标口径并记录后续动作。`,sourceModule:"experiments",sourceId:row.id})}>转为任务</Button><Button size="xs" variant="outline" onClick={()=>router.push(`/copilot?q=${encodeURIComponent(`请分析运营实验“${row.name}”。设计方式：${row.test_design}。基准指标：${JSON.stringify(baseline)}。结果指标：${JSON.stringify(result)}。实验总结：${row.conclusion||"未填写"}。请区分观察变化与因果结论。`)}`)}>AI 分析</Button></div>
          </article>;
        })}</div>}
      </SectionCard>
      <SectionCard title={editing?"编辑实验":"记录新实验"} sub="支持随机 A/B 与普通前后对比；财务指标可为负数。">
        <form onSubmit={save} className="space-y-3">
          <Field label="实验名称"><Input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="例如：洗衣液主图突出除菌卖点"/></Field>
          <div className="grid grid-cols-2 gap-2"><Field label="类型"><AppSelect className={fieldClass} value={form.experiment_type} onChange={e=>setForm({...form,experiment_type:e.target.value})}>{[["main_image","主图"],["title","标题"],["detail","详情页"],["price","价格"],["sku_mix","SKU 组合"],["promotion","推广策略"],["custom","自定义"]].map(([value,label])=><option key={value} value={value}>{label}</option>)}</AppSelect></Field><Field label="设计方式"><AppSelect className={fieldClass} value={form.test_design} onChange={e=>setForm({...form,test_design:e.target.value})}><option value="before_after">普通前后对比</option><option value="randomized_ab">随机 A/B 测试</option></AppSelect></Field></div>
          <div className="grid grid-cols-2 gap-2"><Field label="关联商品"><AppSelect className={fieldClass} value={form.product_id} onChange={e=>setForm({...form,product_id:e.target.value})}><option value="">未关联</option>{data?.products.map(product=><option key={product.id} value={product.id}>{product.name}</option>)}</AppSelect></Field><Field label="状态"><AppSelect className={fieldClass} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{Object.entries(statusNames).map(([value,label])=><option key={value} value={value}>{label}</option>)}</AppSelect></Field></div>
          <Field label="实验目标"><Input value={form.goal} onChange={e=>setForm({...form,goal:e.target.value})}/></Field><Field label="实验假设"><Textarea value={form.hypothesis} onChange={e=>setForm({...form,hypothesis:e.target.value})} placeholder="说明预期变化与理由"/></Field><Field label="原方案"><Textarea value={form.original_plan} onChange={e=>setForm({...form,original_plan:e.target.value})}/></Field><Field label="新方案"><Textarea value={form.new_plan} onChange={e=>setForm({...form,new_plan:e.target.value})}/></Field>
          <div className="grid grid-cols-2 gap-2"><Field label="开始日期"><Input type="date" value={form.start_date} onChange={e=>setForm({...form,start_date:e.target.value})}/></Field><Field label="结束日期"><Input type="date" value={form.end_date} onChange={e=>setForm({...form,end_date:e.target.value})}/></Field></div>
          <Field label="基准指标（JSON）"><Textarea value={form.baseline_metrics} onChange={e=>setForm({...form,baseline_metrics:e.target.value})} placeholder='{"点击率":2.1,"利润":-3}'/></Field><Field label="结果指标（JSON）"><Textarea value={form.result_metrics} onChange={e=>setForm({...form,result_metrics:e.target.value})} placeholder='{"点击率":2.8,"利润":1.2}'/></Field><Field label="实验总结"><Textarea value={form.conclusion} onChange={e=>setForm({...form,conclusion:e.target.value})}/></Field><Field label="下一步建议"><Textarea value={form.next_steps} onChange={e=>setForm({...form,next_steps:e.target.value})}/></Field>
          <div className="flex gap-2"><Button type="submit"><Check size={15}/>保存实验</Button>{editing&&<Button type="button" variant="outline" onClick={()=>open()}>新实验</Button>}</div>
        </form>
      </SectionCard>
    </div>
  </>;
}

function CompetitorsModule({initialRecordId=""}:{initialRecordId?:string}){
 const {data,mode,activeStoreId,update}=useApp();const router=useRouter();const competitors=useRows("competitors","competitors");const prices=useRows("competitor-prices","competitors");const report=useMutationFeedback();const [editing,setEditing]=useState<WorkspaceRow|null>(null);const [selected,setSelected]=useState<string[]>([]);const [form,setForm]=useState({brand:"",product_name:"",product_url:"",platform:"pinduoduo",specifications:"",current_price:"",unit_quantity:"",unit_name:"瓶",selling_points:"",promotion:"",image_url:"",source_note:"",our_product_id:""});const [search,setSearch]=useState("");const [historyId,setHistoryId]=useState("");
 const open=useCallback((row?:WorkspaceRow)=>{setEditing(row||null);setForm(row?{brand:String(row.brand||""),product_name:String(row.product_name),product_url:String(row.product_url||""),platform:String(row.platform),specifications:String(row.specifications||""),current_price:String(row.current_price),unit_quantity:String(row.unit_quantity||""),unit_name:String(row.unit_name||"件"),selling_points:(row.selling_points as string[]||[]).join("，"),promotion:String(row.promotion||""),image_url:String(row.image_url||""),source_note:String(row.source_note||""),our_product_id:String(row.our_product_id||"")}:{brand:"",product_name:"",product_url:"",platform:"pinduoduo",specifications:"",current_price:"",unit_quantity:"",unit_name:"件",selling_points:"",promotion:"",image_url:"",source_note:"",our_product_id:""});},[]);
 const openedId=useRef("");useEffect(()=>{if(!initialRecordId||openedId.current===initialRecordId)return;const row=competitors.rows.find(item=>item.id===initialRecordId);if(!row)return;const timer=window.setTimeout(()=>{open(row);openedId.current=initialRecordId;},0);return()=>window.clearTimeout(timer);},[initialRecordId,competitors.rows,open]);
 const save=async(e:React.FormEvent)=>{e.preventDefault();try{const payload={brand:form.brand,product_name:form.product_name,product_url:form.product_url,platform:form.platform,specifications:form.specifications,current_price:Number(form.current_price),unit_quantity:form.unit_quantity?Number(form.unit_quantity):null,unit_name:form.unit_name,selling_points:form.selling_points.split(/[，,]/).map(s=>s.trim()).filter(Boolean),promotion:form.promotion,image_url:form.image_url,source_note:form.source_note,our_product_id:form.our_product_id||null};if(editing)await competitors.update({id:editing.id,...payload});else await competitors.create(payload);open();}catch(e){report(e,"竞品保存失败");}};
 const compare=competitors.rows.filter(c=>selected.includes(c.id));const history=prices.rows.filter(p=>p.competitor_id===historyId).sort((a,b)=>String(a.recorded_on).localeCompare(String(b.recorded_on))).map(p=>({date:String(p.recorded_on),price:Number(p.price)}));
 return <><PageHead eyebrow={meta.competitors.eyebrow} title={meta.competitors.title} description={meta.competitors.description} action={<Button onClick={()=>open()}><Plus size={16}/>添加竞品</Button>}/><div className="grid gap-4 xl:grid-cols-[minmax(0,1.25fr)_minmax(320px,.75fr)]"><SectionCard title="竞品档案" sub="当前使用人工记录；尚未连接任何自动采集数据源" action={<div className="relative"><Search size={14} className="absolute left-3 top-3 text-muted-foreground"/><Input value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索品牌 / 商品" className="pl-8"/></div>}>{competitors.loading?<p className="text-sm text-muted-foreground">正在读取竞品…</p>:competitors.error?<p role="alert" className="text-sm text-[var(--mc-color-danger)]">{competitors.error}<Button size="sm" onClick={()=>void competitors.refresh()}>重试</Button></p>:competitors.rows.filter(r=>`${r.brand} ${r.product_name} ${r.specifications}`.toLowerCase().includes(search.toLowerCase())&&!r.archived_at).length===0?<Empty title="暂无竞品档案" detail="手动录入竞品售价、规格和卖点后，可查看历史趋势与对比。"/>:<div className="space-y-3">{competitors.rows.filter(r=>`${r.brand} ${r.product_name} ${r.specifications}`.toLowerCase().includes(search.toLowerCase())&&!r.archived_at).map(r=><article key={r.id} className="rounded-2xl border border-border p-4"><div className="flex items-start gap-3"><input type="checkbox" aria-label={`选择 ${r.product_name} 对比`} checked={selected.includes(r.id)} onChange={e=>setSelected(e.target.checked?[...selected,r.id].slice(-4):selected.filter(id=>id!==r.id))}/>{r.image_url?<Image unoptimized width={56} height={56} src={String(r.image_url)} alt="竞品" className="size-14 rounded-xl object-cover"/>:<div className="grid size-14 place-items-center rounded-xl bg-[var(--mc-tint-blue)] text-primary">竞</div>}<div className="min-w-0 flex-1"><div className="flex flex-wrap justify-between gap-2"><div><h3 className="font-semibold">{String(r.product_name)}</h3><p className="mt-1 text-xs text-muted-foreground">{String(r.brand||"未记录品牌")} · {String(r.platform)} · {String(r.specifications||"规格待补充")}</p></div><strong className="number text-lg text-primary">¥{Number(r.current_price).toFixed(2)}</strong></div><p className="mt-2 text-xs leading-5 text-muted-foreground">{(r.selling_points as string[]||[]).join(" · ")||"卖点未记录"}</p><div className="mt-3 flex flex-wrap gap-2"><Button size="xs" variant="outline" onClick={()=>open(r)}>编辑</Button><Button size="xs" variant="outline" onClick={()=>setHistoryId(String(r.id))}>价格趋势</Button><Button size="xs" variant="outline" onClick={async()=>{try{await prices.create({competitor_id:r.id,recorded_on:new Date().toISOString().slice(0,10),price:Number(r.current_price),source_note:"档案当前售价"});notifyFeedback({kind:"success",title:"价格已加入历史趋势"});}catch(e){report(e,"价格记录失败");}}}>记录今日价格</Button><Button size="xs" variant="outline" onClick={()=>{const prompt=`请将以下竞品与自有商品进行差异化分析：\n竞品：${r.product_name}，规格 ${r.specifications}，售价 ¥${r.current_price}，卖点 ${(r.selling_points as string[]||[]).join("、")}。\n关联自有商品：${data?.products.find(p=>p.id===r.our_product_id)?.name||"未关联"}。请指出现有数据、差距和不能确定的内容。`;router.push(`/copilot?q=${encodeURIComponent(prompt)}&competitor=${encodeURIComponent(String(r.id))}`);}}>发送至 AI 分析</Button><Button size="xs" variant="outline" onClick={()=>void createWorkspaceTask({storeId:activeStoreId,mode,update,title:`跟进竞品：${String(r.product_name)}`,detail:`价格 ¥${Number(r.current_price).toFixed(2)}；规格 ${String(r.specifications||"未记录")}；卖点 ${(r.selling_points as string[]||[]).join("、")||"未记录"}。请复核竞品信息并决定是否调整策略。`,sourceModule:"competitors",sourceId:r.id})}>转为任务</Button><Button size="xs" variant="ghost" onClick={()=>void competitors.remove(String(r.id))}><Archive size={13}/>归档</Button></div>{Boolean(r.our_product_id)&&<p className="mt-2 text-[10px] text-muted-foreground">关联自有商品：{data?.products.find(p=>p.id===r.our_product_id)?.name||"商品已移除"}</p>}</div></div></article>)}</div>}</SectionCard>
 <div className="space-y-4"><SectionCard title={editing?"编辑竞品":"添加竞品"} sub="保存人工采集的信息及来源"><form onSubmit={save} className="space-y-3"><div className="grid grid-cols-2 gap-2"><Field label="品牌"><Input value={form.brand} onChange={e=>setForm({...form,brand:e.target.value})}/></Field><Field label="平台"><AppSelect value={form.platform} onChange={e=>setForm({...form,platform:e.target.value})} className={fieldClass}><option value="pinduoduo">拼多多</option><option value="douyin">抖音电商</option><option value="taobao">淘宝</option><option value="jd">京东</option><option value="other">其他</option></AppSelect></Field></div><Field label="商品名称"><Input required value={form.product_name} onChange={e=>setForm({...form,product_name:e.target.value})}/></Field><Field label="商品链接"><Input type="url" value={form.product_url} onChange={e=>setForm({...form,product_url:e.target.value})}/></Field><Field label="规格与容量"><Input value={form.specifications} onChange={e=>setForm({...form,specifications:e.target.value})} placeholder="如：2kg × 2 瓶"/></Field><div className="grid grid-cols-2 gap-2"><Field label="售价（元）"><Input required type="number" min="0" step="0.01" value={form.current_price} onChange={e=>setForm({...form,current_price:e.target.value})}/></Field><Field label="净含量（可选）"><Input type="number" min="0.0001" step="any" value={form.unit_quantity} onChange={e=>setForm({...form,unit_quantity:e.target.value})}/></Field></div><Field label="计量单位"><Input value={form.unit_name} onChange={e=>setForm({...form,unit_name:e.target.value})} placeholder="毫升 / 千克 / 件"/></Field><Field label="核心卖点（逗号分隔）"><Input value={form.selling_points} onChange={e=>setForm({...form,selling_points:e.target.value})}/></Field><Field label="促销活动"><Input value={form.promotion} onChange={e=>setForm({...form,promotion:e.target.value})}/></Field><Field label="图片地址"><Input type="url" value={form.image_url} onChange={e=>setForm({...form,image_url:e.target.value})}/></Field><Field label="对比自有商品"><AppSelect value={form.our_product_id} onChange={e=>setForm({...form,our_product_id:e.target.value})} className={fieldClass}><option value="">暂不关联</option>{data?.products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</AppSelect></Field><Field label="来源备注"><Input value={form.source_note} onChange={e=>setForm({...form,source_note:e.target.value})}/></Field><Button type="submit">保存档案</Button>{editing&&<Button type="button" variant="outline" onClick={()=>open()}>新建</Button>}</form></SectionCard><SectionCard title="价格历史趋势" sub="按竞品与手动记录日期展示">{historyId?<>{history.length?<div className="h-48"><ResponsiveContainer width="100%" height="100%"><LineChart data={history}><XAxis dataKey="date" tick={{fontSize:10}}/><YAxis width={45} tick={{fontSize:10}}/><Tooltip/><Line type="monotone" dataKey="price" name="售价（元）" stroke="#3b91eb" strokeWidth={2} dot/></LineChart></ResponsiveContainer></div>:<Empty title="还没有价格历史" detail="点击竞品卡片中的“记录今日价格”。"/>}<div className="mt-3 space-y-1">{prices.rows.filter(p=>p.competitor_id===historyId).map(p=><p key={p.id} className="flex justify-between text-xs text-muted-foreground"><span>{String(p.recorded_on)} · {String(p.source_note||"人工记录")}</span><b>¥{Number(p.price).toFixed(2)}</b></p>)}</div></>:<p className="text-sm text-muted-foreground">从左侧竞品卡片选择“价格趋势”。</p>}</SectionCard></div></div>
 {compare.length>0&&<SectionCard title="竞品横向对比" sub={`已选择 ${compare.length} 个竞品，单位价格仅在填写了净含量时计算`}><div className="overflow-x-auto"><table className="w-full min-w-[660px] text-left text-sm"><thead><tr className="text-xs text-muted-foreground">{["项目",...compare.map(c=>String(c.product_name))].map(c=><th key={c} className="border-b p-3">{c}</th>)}</tr></thead><tbody>{[["品牌",(c:WorkspaceRow)=>c.brand||"—"],["规格",(c:WorkspaceRow)=>c.specifications||"—"],["售价",(c:WorkspaceRow)=>`¥${Number(c.current_price).toFixed(2)}`],["单位价格",(c:WorkspaceRow)=>c.unit_quantity?`¥${(Number(c.current_price)/Number(c.unit_quantity)).toFixed(2)} / ${c.unit_name}`:"数据不足"],["核心卖点",(c:WorkspaceRow)=>(c.selling_points as string[]||[]).join("、")||"—"],["定位",(c:WorkspaceRow)=>c.promotion||"未记录"]].map(([label,fn])=><tr key={String(label)} className="border-b border-border"><th className="p-3 text-xs text-muted-foreground">{label as string}</th>{compare.map(c=><td key={c.id} className="p-3 text-xs">{(fn as (r:WorkspaceRow)=>string)(c)}</td>)}</tr>)}</tbody></table></div></SectionCard>}
 </>;
}

const serviceCategories:Record<string,string>={presales:"售前咨询",specification:"商品规格",usage:"产品使用方法",logistics:"物流问题",leakage:"漏液与包装破损",refund:"退款退货",complaint:"投诉处理",negative_review:"差评沟通",follow_up:"售后回访",other:"其他"};
function ServiceModule({initialRecordId=""}:{initialRecordId?:string}){
 const {mode,activeStoreId,data,role,update}=useApp();const router=useRouter();const notes=useRows("notes","notes");const templates=useRows("service-templates","service");const cases=useRows("service-cases","service");const logs=useRows("service-case-logs","service");const report=useMutationFeedback();const [tab,setTab]=useState<"templates"|"cases">("templates");const [editTemplate,setEditTemplate]=useState<WorkspaceRow|null>(null);const [templateForm,setTemplateForm]=useState({title:"",category:"presales",body:"",variables:"product_name, order_number, customer_name"});const [caseId,setCaseId]=useState("");const [caseForm,setCaseForm]=useState({order_number:"",customer_name:"",product_id:"",assigned_to:"",issue_category:"usage",description:"",status:"open",resolution:"",compensation_amount:"0"});const [attachments,setAttachments]=useState<string[]>([]);const [search,setSearch]=useState("");const [vars,setVars]=useState<Record<string,string>>({});const [caseFilter,setCaseFilter]=useState("all");const canEdit=mode==="local"||role!=="viewer";
 const openTemplate=(row?:WorkspaceRow)=>{setEditTemplate(row||null);setTemplateForm(row?{title:String(row.title),category:String(row.category),body:String(row.body),variables:(row.variables as string[]||[]).join(", ")}:{title:"",category:"presales",body:"",variables:"product_name, order_number, customer_name"});};
 const saveTemplate=async(e:React.FormEvent)=>{e.preventDefault();try{const payload={...templateForm,variables:templateForm.variables.split(/[，,]/).map(s=>s.trim()).filter(Boolean)};if(editTemplate)await templates.update({id:editTemplate.id,...payload});else await templates.create(payload);openTemplate();}catch(e){report(e,"话术保存失败");}};
 const openCase=useCallback((row?:WorkspaceRow)=>{setCaseId(String(row?.id||""));setAttachments((row?.attachment_paths as string[]||[]));setCaseForm(row?{order_number:String(row.order_number),customer_name:String(row.customer_name),product_id:String(row.product_id||""),assigned_to:String(row.assigned_to||""),issue_category:String(row.issue_category),description:String(row.description),status:String(row.status),resolution:String(row.resolution),compensation_amount:String(row.compensation_amount)}:{order_number:"",customer_name:"",product_id:"",assigned_to:"",issue_category:"usage",description:"",status:"open",resolution:"",compensation_amount:"0"});},[]);
 const openedId=useRef("");useEffect(()=>{if(!initialRecordId||openedId.current===initialRecordId)return;const row=cases.rows.find(item=>item.id===initialRecordId);if(!row)return;const timer=window.setTimeout(()=>{setTab("cases");openCase(row);openedId.current=initialRecordId;},0);return()=>window.clearTimeout(timer);},[initialRecordId,cases.rows,openCase]);
 const saveCase=async(e:React.FormEvent)=>{e.preventDefault();try{const payload={...caseForm,product_id:caseForm.product_id||null,assigned_to:caseForm.assigned_to||null,attachment_paths:attachments,compensation_amount:Number(caseForm.compensation_amount)};const old=cases.rows.find(c=>c.id===caseId);if(caseId){await cases.update({id:caseId,...payload});if(old?.status!==caseForm.status)await logs.create({case_id:caseId,action:caseForm.status==="resolved"?"resolved":"status_changed",detail:`状态更新为：${caseForm.status}`});if(old?.resolution!==caseForm.resolution)await logs.create({case_id:caseId,action:"note_added",detail:"更新了处理结果"});if(JSON.stringify(old?.attachment_paths||[])!==JSON.stringify(attachments))await logs.create({case_id:caseId,action:"attachment_added",detail:"更新了工单附件"});}else{const created=await cases.create(payload);if(created&&"id"in(created as object))await logs.create({case_id:String((created as {id:string}).id),action:"created",detail:"创建售后工单"});if(attachments.length)await logs.create({case_id:String((created as {id:string}).id),action:"attachment_added",detail:"上传了工单附件"});}openCase();}catch(e){report(e,"售后工单保存失败");}};
 const fill=(template:string)=>template.replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g,(_,key:string)=>vars[key]||`{{${key}}}`);
 const copy=async(text:string)=>{try{await navigator.clipboard.writeText(text);notifyFeedback({kind:"success",title:"回复已复制",description:"可以粘贴到客服沟通窗口。"});}catch{report(new Error("浏览器未授予剪贴板权限"),"复制失败");}};
 const upload=async(file:File)=>{if(mode!=="cloud"||!activeStoreId){report(new Error("附件需要连接云端店铺并完成数据库迁移"),"当前模式不支持附件上传");return null;}if(file.size>10*1024*1024||!/[.](jpg|jpeg|png|webp|pdf)$/i.test(file.name)){report(new Error("仅支持 JPG、PNG、WebP 或 PDF，最大 10MB"),"附件不符合要求");return null;}try{const id=caseId||crypto.randomUUID();const ext=file.name.split(".").pop()?.toLowerCase()||"bin";const path=`${activeStoreId}/cases/${id}/${crypto.randomUUID()}.${ext}`;const {error}=await createBrowserSupabaseClient().storage.from("moonclean-service-attachments").upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;notifyFeedback({kind:"success",title:"附件已上传",description:"上传到当前店铺的私有存储。"});return path;}catch(e){report(e,"附件上传失败");return null;}};
 return <><PageHead eyebrow={meta.service.eyebrow} title={meta.service.title} description={meta.service.description} action={<div className="flex gap-2"><Button variant={tab==="templates"?"default":"outline"} onClick={()=>setTab("templates")}><MessageSquareText size={15}/>话术库</Button><Button variant={tab==="cases"?"default":"outline"} onClick={()=>setTab("cases")}><Headset size={15}/>售后工单</Button></div>}/>
 {tab==="templates"?<div className="grid gap-4 xl:grid-cols-[minmax(0,1.25fr)_minmax(320px,.75fr)]"><SectionCard title="客服话术库" sub="模板仅作为候选回复，涉及退款或赔付需人工确认" action={<div className="relative"><Search size={14} className="absolute left-3 top-3 text-muted-foreground"/><Input value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索话术" className="pl-8"/></div>}>{templates.loading?<p>加载话术中…</p>:templates.error?<p role="alert" className="text-sm text-[var(--mc-color-danger)]">{templates.error}<Button size="sm" onClick={()=>void templates.refresh()}>重试</Button></p>:templates.rows.filter(t=>!t.archived_at&&`${t.title} ${t.body} ${serviceCategories[String(t.category)]}`.toLowerCase().includes(search.toLowerCase())).length===0?<Empty title="话术库还是空的" detail="先创建经过审核的标准回复，也可以由右侧表单添加。"/>:<div className="space-y-3">{templates.rows.filter(t=>!t.archived_at&&`${t.title} ${t.body} ${serviceCategories[String(t.category)]}`.toLowerCase().includes(search.toLowerCase())).map(t=><article key={t.id} className="rounded-2xl border border-border p-4"><div className="flex justify-between gap-3"><div><h3 className="font-semibold">{String(t.title)}</h3><p className="mt-1 text-[10px] text-muted-foreground">{serviceCategories[String(t.category)]}</p></div><Button size="xs" variant="outline" onClick={()=>openTemplate(t)}>编辑</Button></div><p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{fill(String(t.body))}</p><div className="mt-3 flex flex-wrap gap-2">{(t.variables as string[]||[]).map(v=><label key={v} className="text-[10px] text-muted-foreground">{v}<Input value={vars[v]||""} onChange={e=>setVars({...vars,[v]:e.target.value})} className="mt-1 h-8 w-36 text-xs" placeholder={`填写 ${v}`}/></label>)}</div><div className="mt-3 flex gap-2"><Button size="xs" onClick={()=>void copy(fill(String(t.body)))}><Copy size={13}/>复制完整回复</Button><Button size="xs" variant="outline" onClick={()=>{router.push(`/copilot?q=${encodeURIComponent(`请根据已审核话术“${t.title}”协助拟定回复。话术内容：${t.body}。不要承诺未确认的退款、赔付或功效。`)}`);}}>AI 辅助润色</Button><Button size="xs" variant="ghost" onClick={()=>void templates.remove(String(t.id))}><Archive size={13}/>归档</Button></div></article>)}</div>}</SectionCard><SectionCard title={editTemplate?"编辑话术":"新增话术"} sub="支持 {{product_name}} 等变量模板"><form onSubmit={saveTemplate} className="space-y-3"><Field label="话术名称"><Input required value={templateForm.title} onChange={e=>setTemplateForm({...templateForm,title:e.target.value})}/></Field><Field label="分类"><AppSelect value={templateForm.category} onChange={e=>setTemplateForm({...templateForm,category:e.target.value})} className={fieldClass}>{Object.entries(serviceCategories).map(([v,l])=><option key={v} value={v}>{l}</option>)}</AppSelect></Field><Field label="回复内容"><Textarea required rows={7} value={templateForm.body} onChange={e=>setTemplateForm({...templateForm,body:e.target.value})} placeholder="您好，关于 {{product_name}} 的使用问题……"/></Field><Field label="可用变量（逗号分隔）"><Input value={templateForm.variables} onChange={e=>setTemplateForm({...templateForm,variables:e.target.value})}/></Field><div className="flex gap-2"><Button type="submit">保存话术</Button><Button type="button" variant="outline" onClick={()=>openTemplate()}>清空</Button></div></form></SectionCard></div>:<div className="grid gap-4 xl:grid-cols-[minmax(0,1.3fr)_minmax(320px,.7fr)]"><SectionCard title="售后工单" sub="记录问题、负责人、处置结果及处理时间线" action={<AppSelect value={caseFilter} onChange={e=>setCaseFilter(e.target.value)} className="rounded-xl border border-border bg-card px-3 py-2 text-xs"><option value="all">全部状态</option>{[["open","待处理"],["processing","处理中"],["waiting_customer","等待客户"],["resolved","已解决"],["closed","已关闭"]].map(([v,l])=><option key={v} value={v}>{l}</option>)}</AppSelect>}>{cases.loading?<p>工单加载中…</p>:cases.error?<p role="alert" className="text-sm text-[var(--mc-color-danger)]">{cases.error}<Button size="sm" onClick={()=>void cases.refresh()}>重试</Button></p>:cases.rows.filter(c=>caseFilter==="all"||c.status===caseFilter).length===0?<Empty title="暂无售后工单" detail="记录问题后，可持续追踪处理状态和客户反馈。"/>:<div className="space-y-3">{cases.rows.filter(c=>caseFilter==="all"||c.status===caseFilter).map(c=><article key={c.id} className="rounded-2xl border border-border p-4"><div className="flex flex-wrap justify-between gap-2"><div><h3 className="font-semibold">{serviceCategories[String(c.issue_category)]} · {String(c.order_number||"无订单号")}</h3><p className="mt-1 text-xs text-muted-foreground">{String(c.customer_name||"未填写客户")} · {String(c.status)} · {new Date(String(c.created_at)).toLocaleString("zh-CN")}</p></div><Button size="sm" variant="outline" onClick={()=>{openCase(c);setCaseId(String(c.id));}}>处理工单</Button></div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{String(c.description)}</p>{Boolean(c.resolution)&&<p className="mt-2 rounded-lg bg-[var(--mc-tint-blue)] p-2 text-xs">处理结果：{String(c.resolution)} · 赔付 ¥{Number(c.compensation_amount).toFixed(2)}</p>}{(c.attachment_paths as string[]||[]).length>0&&<details className="mt-2 text-xs"><summary className="cursor-pointer text-muted-foreground">附件（{(c.attachment_paths as string[]).length}）</summary><div className="mt-2 space-y-1">{(c.attachment_paths as string[]).map(path=><button key={path} className="block text-primary underline" onClick={async()=>{try{const {data,error}=await createBrowserSupabaseClient().storage.from("moonclean-service-attachments").createSignedUrl(path,300);if(error)throw error;window.open(data.signedUrl,"_blank","noopener,noreferrer");}catch(e){report(e,"无法打开附件");}}}>{path.split("/").pop()}</button>)}</div></details>}<details className="mt-3 text-xs"><summary className="cursor-pointer text-muted-foreground">处理记录</summary><div className="mt-2 space-y-1">{logs.rows.filter(l=>l.case_id===c.id).map(l=><p key={l.id} className="border-l-2 border-border pl-2 text-muted-foreground">{new Date(String(l.created_at)).toLocaleString("zh-CN")} · {String(l.detail)}</p>)}</div></details><Button size="xs" variant="outline" className="mt-2" onClick={async()=>{try{const note=await notes.create({title:`售后案例：${serviceCategories[String(c.issue_category)]}`,category:"售后案例",body_markdown:`## 客户问题\n\n${c.description}\n\n## 处理结果\n\n${c.resolution||"待补充"}\n\n## 赔付\n\n¥${Number(c.compensation_amount).toFixed(2)}`,related_type:"service_case",related_id:c.id});if(note&&"id"in(note as object))await cases.update({id:c.id,linked_note_id:(note as {id:string}).id});notifyFeedback({kind:"success",title:"售后案例已沉淀到运营备忘录"});}catch(e){report(e,"沉淀案例失败");}}}>沉淀到运营备忘录</Button><Button size="xs" variant="outline" className="mt-2 ml-2" onClick={()=>void createWorkspaceTask({storeId:activeStoreId,mode,update,title:`跟进售后工单：${String(c.order_number||serviceCategories[String(c.issue_category)])}`,detail:String(c.description),sourceModule:"service-cases",sourceId:c.id})}>转为任务</Button>{Boolean(c.linked_note_id)&&<Button size="xs" variant="outline" className="mt-2 ml-2" onClick={()=>router.push(`/notes?id=${String(c.linked_note_id)}`)}>查看关联备忘录</Button>}<Button size="xs" variant="outline" className="mt-2 ml-2" onClick={()=>{router.push(`/copilot?q=${encodeURIComponent(`请根据售后工单为客服生成一个候选回复，不要承诺退款或赔付，需人工确认。问题：${c.description}`)}`);}}>AI 拟定回复</Button></article>)}</div>}</SectionCard><SectionCard title={caseId?"处理售后工单":"新建售后工单"} sub="附件上传至店铺私有 Supabase Storage"><form onSubmit={saveCase} className="space-y-3"><div className="grid grid-cols-2 gap-2"><Field label="订单号"><Input value={caseForm.order_number} onChange={e=>setCaseForm({...caseForm,order_number:e.target.value})}/></Field><Field label="客户称呼"><Input value={caseForm.customer_name} onChange={e=>setCaseForm({...caseForm,customer_name:e.target.value})}/></Field></div><Field label="关联商品"><AppSelect value={caseForm.product_id} onChange={e=>setCaseForm({...caseForm,product_id:e.target.value})} className={fieldClass}><option value="">未关联</option>{data?.products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</AppSelect></Field><Field label="负责人用户 ID（可选）"><Input value={caseForm.assigned_to} onChange={e=>setCaseForm({...caseForm,assigned_to:e.target.value})} placeholder="粘贴已授权成员 UUID"/></Field><div className="grid grid-cols-2 gap-2"><Field label="问题类型"><AppSelect value={caseForm.issue_category} onChange={e=>setCaseForm({...caseForm,issue_category:e.target.value})} className={fieldClass}>{Object.entries(serviceCategories).map(([v,l])=><option key={v} value={v}>{l}</option>)}</AppSelect></Field><Field label="处理状态"><AppSelect value={caseForm.status} onChange={e=>setCaseForm({...caseForm,status:e.target.value})} className={fieldClass}><option value="open">待处理</option><option value="processing">处理中</option><option value="waiting_customer">等待客户</option><option value="resolved">已解决</option><option value="closed">已关闭</option></AppSelect></Field></div><Field label="问题描述"><Textarea required rows={4} value={caseForm.description} onChange={e=>setCaseForm({...caseForm,description:e.target.value})}/></Field><Field label="处理结果"><Textarea value={caseForm.resolution} onChange={e=>setCaseForm({...caseForm,resolution:e.target.value})}/></Field><Field label="赔付金额（需人工确认）"><Input type="number" min="0" step="0.01" value={caseForm.compensation_amount} onChange={e=>setCaseForm({...caseForm,compensation_amount:e.target.value})}/></Field><Field label="附件（JPG / PNG / WebP / PDF，≤10MB）"><Input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" disabled={!canEdit} onChange={async e=>{const file=e.target.files?.[0];if(!file)return;const path=await upload(file);if(path)setAttachments(current=>[...current,path]);}}/></Field>{attachments.length>0&&<div className="space-y-1">{attachments.map(path=><p key={path} className="flex items-center justify-between rounded-lg bg-[var(--mc-tint-blue)] px-2 py-1 text-xs"><span className="truncate">{path.split("/").pop()}</span><button type="button" aria-label="移除附件" onClick={()=>setAttachments(current=>current.filter(item=>item!==path))}>移除</button></p>)}</div>}<div className="flex gap-2"><Button type="submit" disabled={!canEdit}><Check size={15}/>{caseId?"保存处理记录":"创建售后工单"}</Button><Button type="button" variant="outline" onClick={()=>openCase()}>新建</Button>{caseId&&<Button type="button" variant="outline" onClick={()=>{router.push(`/copilot?q=${encodeURIComponent(`请作为客服辅助，根据客户问题起草一条候选回复并标记需要人工确认。问题：${caseForm.description}`)}`);}}>AI 客服辅助</Button>}</div><p className="text-[10px] leading-5 text-muted-foreground">AI 回复仅供人工审核，不会自动发送，也不会自动承诺退款、赔偿或产品功效。</p></form></SectionCard></div>}
 </>;
}

function CopilotModule({initialQuestion="",initialCompetitorId="",initialConversationId=""}:{initialQuestion?:string;initialCompetitorId?:string;initialConversationId?:string}){
 const {mode,activeStoreId,data,role,update}=useApp();const conversations=useRows("copilot-conversations","copilot");const messages=useRows("copilot-messages","copilot");const notes=useRows("notes","notes");const usage=useRows("copilot-usage","copilot");const report=useMutationFeedback();const [conversationId,setConversationId]=useState(initialConversationId);const [forceNewConversation,setForceNewConversation]=useState(Boolean(initialQuestion));const [question,setQuestion]=useState(initialQuestion);const [sending,setSending]=useState(false);const [streamedAnswer,setStreamedAnswer]=useState("");const [search,setSearch]=useState("");const [configured,setConfigured]=useState<boolean|null>(null);const [pinOpen,setPinOpen]=useState(false);const [productIds,setProductIds]=useState<string[]>([]);const [competitorIds]=useState<string[]>(initialCompetitorId?[initialCompetitorId]:[]);const [historyCategory,setHistoryCategory]=useState("全部分类");const [conversationCategories,setConversationCategories]=useState<Record<string,string>>({});const [editingConversationId,setEditingConversationId]=useState("");const [editingTitle,setEditingTitle]=useState("");const [messageFilter,setMessageFilter]=useState("all");const [expandedMessageIds,setExpandedMessageIds]=useState<string[]>([]);
 useEffect(()=>{if(mode!=="cloud"||!activeStoreId){const frame=window.requestAnimationFrame(()=>setConfigured(false));return()=>window.cancelAnimationFrame(frame);}let cancelled=false;fetch(`/api/stores/${activeStoreId}/ai/deepseek`,{credentials:"same-origin",cache:"no-store"}).then(r=>r.json()).then(data=>{if(!cancelled)setConfigured(Boolean(data.configured));}).catch(()=>{if(!cancelled)setConfigured(false);});return()=>{cancelled=true;};},[activeStoreId,mode]);
 const activeConversationId=conversationId||(forceNewConversation?"":String(conversations.rows.find(c=>!c.deleted_at)?.id||""));
 const messagesByConversation=useMemo(()=>{const groups=new Map<string,WorkspaceRow[]>();for(const message of messages.rows){const id=String(message.conversation_id);const group=groups.get(id)||[];group.push(message);groups.set(id,group)}for(const group of groups.values())group.sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));return groups},[messages.rows]);const activeMessages=messagesByConversation.get(activeConversationId)||[];
 const categoryStorageKey=activeStoreId?`moonclean-copilot-categories-v1:${activeStoreId}`:"";
 useEffect(()=>{const frame=window.requestAnimationFrame(()=>{if(!categoryStorageKey){setConversationCategories({});return;}try{const saved=JSON.parse(localStorage.getItem(categoryStorageKey)||"{}");setConversationCategories(saved&&typeof saved==="object"&&!Array.isArray(saved)?saved:{})}catch{setConversationCategories({})}});return()=>window.cancelAnimationFrame(frame)},[categoryStorageKey]);
 const visibleConversations=conversations.rows.filter(c=>{if(c.deleted_at)return false;const category=conversationCategories[c.id]||"未分类";if(historyCategory!=="全部分类"&&category!==historyCategory)return false;const query=search.trim().toLowerCase();if(!query)return true;return String(c.title).toLowerCase().includes(query)||(messagesByConversation.get(String(c.id))||[]).some(m=>String(m.content).toLowerCase().includes(query));}).sort((a,b)=>String(b.updated_at||b.created_at).localeCompare(String(a.updated_at||a.created_at)));
 const visibleMessages=activeMessages.filter(m=>messageFilter==="all"||m.role===messageFilter);
 const latestAssistantId=[...activeMessages].reverse().find(m=>m.role==="assistant")?.id||"";
 const assignConversationCategory=(id:string,value:string)=>{const next={...conversationCategories,[id]:value};if(value==="未分类")delete next[id];setConversationCategories(next);try{if(categoryStorageKey)localStorage.setItem(categoryStorageKey,JSON.stringify(next));}catch{/* Continue with the current session if browser storage is unavailable. */}notifyFeedback({kind:"success",title:`已分类为「${value}」`,description:"分类已保存到这台设备，可用上方筛选快速查找。"});};
 const saveConversationTitle=async(id:string)=>{const value=editingTitle.trim().slice(0,180);if(!value){setEditingConversationId("");return;}try{await conversations.update({id,title:value});setEditingConversationId("");notifyFeedback({kind:"success",title:"对话标题已更新"})}catch(e){report(e,"修改对话标题失败")}};
 const sendWithKey=async(apiKey:string)=>{if(!question.trim()||sending||!activeStoreId)return;const asked=question.trim();setSending(true);setStreamedAnswer("");try{let id=activeConversationId;if(!id){const response=await fetch(`/api/stores/${activeStoreId}/workspace/copilot-conversations`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({title:asked.slice(0,80),product_ids:productIds,competitor_ids:competitorIds})});const row=await response.json();if(!response.ok)throw new Error(row.error||"无法创建对话");id=row.id;setConversationId(id);setForceNewConversation(false);await conversations.refresh();}const response=await fetch(`/api/stores/${activeStoreId}/workspace/copilot`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({apiKey,conversationId:id,question:asked,productIds,competitorIds})});let answer="";const result=await readAiTextStream(response,(delta)=>{answer+=delta;setStreamedAnswer(answer);});setQuestion("");await conversations.refresh();await messages.refresh();await usage.refresh();notifyFeedback({kind:"success",title:"分析已完成",description:`使用 ${String(result?.model||"DeepSeek")}，内容已保存到对话历史。`});}catch(e){report(e,"AI 分析失败");}finally{setSending(false);setStreamedAnswer("");}};
 const send=async(e?:React.FormEvent)=>{e?.preventDefault();if(!question.trim()||sending)return;if(mode!=="cloud"){report(new Error("切换至云端数据并登录后，AI 才能读取店铺经营数据。"),"AI 助手不可用");return;}if(role==="viewer"){report(new Error("查看者角色不能创建或保存 AI 对话。"),"当前角色为只读");return;}if(!activeStoreId)return;const cachedKey=await getCachedDeepSeekKey(activeStoreId);if(cachedKey)await sendWithKey(cachedKey);else setPinOpen(true);};
 const createTask=async(content:string)=>{try{const titleLine=content.split("\n").find(line=>line.trim())?.replace(/^#+\s*/,"").slice(0,100)||"复核经营建议";await createWorkspaceTask({storeId:activeStoreId,mode,update,title:`AI 建议跟进：${titleLine}`,detail:content,sourceModule:"copilot-conversations",sourceId:activeConversationId||undefined});}catch(e){report(e,"创建任务失败");}};
 const saveNote=async(content:string)=>{try{const row=await notes.create({title:`AI 经营建议 · ${new Date().toLocaleDateString("zh-CN")}`,category:"AI 经营建议",body_markdown:content,related_type:activeConversationId?"copilot_conversation":null,related_id:activeConversationId||null});void row;}catch(e){report(e,"保存为备忘录失败");}};
 const createExperiment=async(content:string)=>{try{const note=await notes.create({title:"AI 运营建议实验来源",category:"AI 经营建议",body_markdown:content,related_type:activeConversationId?"copilot_conversation":null,related_id:activeConversationId||null});const response=await fetch(`/api/stores/${activeStoreId}/workspace/experiments`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:"AI 建议实验草稿",experiment_type:"custom",status:"draft",test_design:"before_after",source_note_id:note&&"id"in(note as object)?(note as {id:string}).id:null,goal:"根据 AI 分析建议验证可行性",hypothesis:content.slice(0,3900),original_plan:"记录当前运营方案及基准指标。",new_plan:"根据建议设计一个可控的小范围调整，并记录观察指标。"})});const result=await response.json();if(!response.ok)throw new Error(result.error||"创建实验失败");notifyFeedback({kind:"success",title:"已生成实验草稿",description:"AI 建议已先保存为备忘录来源；请在实验室补全指标与时间。"});}catch(e){report(e,"生成实验失败");}};
 return <><PageHead eyebrow={meta.copilot.eyebrow} title={meta.copilot.title} description={meta.copilot.description} action={<Button variant="outline" onClick={()=>{setConversationId("");setForceNewConversation(true);setQuestion("");}}><FilePlus2 size={15}/>新对话</Button>}/><div className="grid gap-4 xl:grid-cols-[260px_minmax(0,1fr)]"><aside className="glass-card rounded-[20px] p-3 sm:p-4"><div className="mb-3 flex items-center justify-between"><div><h2 className="text-sm font-semibold">对话库</h2><p className="mt-0.5 text-[10px] text-muted-foreground">{visibleConversations.length} 个会话 · 分类保存在本机</p></div></div><div className="relative mb-2"><Search size={14} className="absolute left-3 top-3 text-muted-foreground"/><Input value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索标题和对话内容" className="pl-8"/></div><AppSelect aria-label="按分类筛选对话" value={historyCategory} onChange={e=>setHistoryCategory(e.target.value)} className="mb-3 h-9 w-full rounded-xl border border-border bg-card px-3 text-xs"><option value="全部分类">全部分类</option><option value="未分类">未分类</option>{COPILOT_CATEGORIES.map(name=><option key={name} value={name}>{name}</option>)}</AppSelect>{conversations.loading?<p className="text-xs text-muted-foreground">加载中…</p>:conversations.error?<p role="alert" className="text-xs text-[var(--mc-color-danger)]">{conversations.error}<button className="underline" onClick={()=>void conversations.refresh()}>重试</button></p>:visibleConversations.length===0?<Empty title={search?"没有匹配的对话":"还没有对话"} detail="新建对话后，可在这里搜索、改名和分类。"/>:<div className="max-h-[55vh] space-y-2 overflow-y-auto pr-1">{visibleConversations.map(c=><article key={c.id} className={`rounded-xl border p-2 ${c.id===activeConversationId?"border-primary/40 bg-[var(--mc-tint-blue)]":"border-border bg-card hover:bg-[var(--mc-tint-blue)]/50"}`}>{editingConversationId===c.id?<form className="flex gap-1" onSubmit={e=>{e.preventDefault();void saveConversationTitle(c.id);}}><Input autoFocus maxLength={180} value={editingTitle} onChange={e=>setEditingTitle(e.target.value)} aria-label="对话标题" className="h-8 min-w-0 text-xs"/><Button size="icon-xs" type="submit" title="保存标题"><Check size={13}/></Button><Button size="icon-xs" type="button" variant="ghost" title="取消修改" onClick={()=>setEditingConversationId("")}><X size={13}/></Button></form>:<div className="flex items-start gap-1"><button className="min-w-0 flex-1 px-1 py-1 text-left" onClick={()=>{setConversationId(c.id);setForceNewConversation(false);setMessageFilter("all");}}><span className="block truncate text-xs font-medium text-foreground">{String(c.title||"新对话")}</span><span className="mt-1 block text-[10px] text-muted-foreground">{new Date(String(c.updated_at||c.created_at)).toLocaleDateString("zh-CN")} · {(messagesByConversation.get(String(c.id))||[]).length} 条消息 · {conversationCategories[c.id]||"未分类"}</span></button><Button size="icon-xs" variant="ghost" title="修改标题" onClick={()=>{setEditingConversationId(c.id);setEditingTitle(String(c.title||""));}}><Pencil size={12}/></Button><Button size="icon-xs" variant="ghost" title="删除对话" onClick={async()=>{try{await conversations.remove(c.id);if(c.id===activeConversationId){setConversationId("");setForceNewConversation(true);}await messages.refresh();}catch(e){report(e,"删除对话失败")}}}><Trash2 size={12}/></Button></div>}<AppSelect aria-label={`“${String(c.title)}”的分类`} value={conversationCategories[c.id]||"未分类"} onChange={e=>assignConversationCategory(c.id,e.target.value)} className="mt-1 h-7 w-full rounded-lg border border-border bg-card px-2 text-[10px]"><option value="未分类">未分类</option>{COPILOT_CATEGORIES.map(name=><option key={name} value={name}>{name}</option>)}</AppSelect></article>)}</div>}<div className="mt-4 rounded-xl bg-[var(--mc-tint-blue)] p-3 text-[10px] leading-5 text-muted-foreground">对话与回答保存在当前店铺。分类仅保存在这台设备；AI 回复可折叠、筛选、复制，或收纳到备忘录、待办和实验。</div></aside>
 <SectionCard title={activeConversationId?String(conversations.rows.find(c=>c.id===activeConversationId)?.title||"AI 运营分析"):"开始一次经营分析"} sub={mode!=="cloud"?"本地演示数据不会发送给 AI。切换云端店铺后，助手会使用授权经营数据。":configured===false?"请先到AI 设置中输入 DeepSeek API Key。":"对话会保存在当前云端店铺，并记录真实数据来源。"} className="flex min-h-[68vh] flex-col"><div className="mb-3 flex flex-wrap gap-2"><span className={`rounded-full px-2.5 py-1 text-[10px] ${configured?"bg-[var(--mc-tint-green)] text-[var(--mc-color-success)]":"bg-[var(--mc-tint-blue)] text-muted-foreground"}`}>{configured?"DeepSeek 已配置":"DeepSeek 未连接"}</span><span className="rounded-full bg-[var(--mc-tint-blue)] px-2.5 py-1 text-[10px] text-muted-foreground">数据范围：近 30 日 · 商品 · 成本版本 · 实验 · 竞品</span><span className="rounded-full bg-[var(--mc-tint-blue)] px-2.5 py-1 text-[10px] text-muted-foreground">近500次调用 {usage.rows.length} 条 · Token {usage.rows.reduce((n,row)=>n+Number(row.prompt_tokens||0)+Number(row.completion_tokens||0),0)} · 失败 {usage.rows.filter(row=>row.outcome==="failed").length}</span></div><div className="mb-3"><p className="mb-2 text-[11px] font-semibold text-muted-foreground">选择关联商品（可选）</p><div className="flex flex-wrap gap-1.5">{data?.products.slice(0,10).map(p=><button key={p.id} type="button" onClick={()=>setProductIds(current=>current.includes(p.id)?current.filter(id=>id!==p.id):[...current,p.id].slice(-10))} className={`rounded-full border px-2.5 py-1 text-[10px] ${productIds.includes(p.id)?"border-border bg-[var(--mc-tint-blue)] text-primary":"border-border text-muted-foreground"}`}>{p.name}</button>)}</div></div><div className="mb-2 flex flex-wrap items-center justify-between gap-2"><p className="text-[10px] text-muted-foreground">{activeMessages.length} 条消息 · 长回答可展开查看</p><AppSelect aria-label="筛选对话消息" value={messageFilter} onChange={e=>setMessageFilter(e.target.value)} className="h-8 rounded-lg border border-border bg-card px-2 text-[10px]"><option value="all">全部消息</option><option value="assistant">只看 AI 回答</option><option value="user">只看我的提问</option></AppSelect></div><div className="flex-1 min-h-[320px] space-y-3 overflow-y-auto rounded-2xl bg-[var(--mc-tint-blue)] p-3 md:p-4">{visibleMessages.length===0?<div className="mx-auto max-w-xl py-10 text-center"><span className="mx-auto grid size-12 place-items-center rounded-2xl bg-[var(--mc-tint-blue)] text-primary"><Sparkles size={22}/></span><h3 className="mt-3 text-sm font-semibold">{activeMessages.length?"此筛选下没有消息":"今天想分析什么？"}</h3><p className="mt-1 text-xs text-muted-foreground">{activeMessages.length?"切换消息筛选，或查看完整对话。":"例如：哪个商品利润最高？近期 ROAS 合理吗？哪些实验值得继续？"}</p>{!activeMessages.length&&<div className="mt-4 flex flex-wrap justify-center gap-2">{["近 30 天经营表现与主要风险是什么？","哪些商品成本数据不完整，影响利润判断？","现有竞品与自有商品有哪些可验证的差异？","哪些运营实验可以继续，依据是什么？"].map(q=><button key={q} onClick={()=>setQuestion(q)} className="rounded-xl border border-border bg-card px-3 py-2 text-left text-xs text-muted-foreground hover:bg-[var(--mc-tint-blue)]">{q}</button>)}</div>}</div>:visibleMessages.map(m=>{const content=String(m.content);const isLong=m.role==="assistant"&&content.length>900;const collapsed=isLong&&m.id!==latestAssistantId&&!expandedMessageIds.includes(String(m.id));return <article key={m.id} className={`max-w-[92%] rounded-2xl p-3 md:p-4 ${m.role==="user"?"ml-auto bg-[var(--mc-tint-blue)] text-foreground":"border border-border bg-card text-foreground"}`}><p className="mb-2 text-[10px] font-semibold text-muted-foreground">{m.role==="user"?"你":"MoonClean Copilot"}</p><div className={`relative ${collapsed?"max-h-36 overflow-hidden":""}`}><MarkdownReply content={content}/>{collapsed&&<div className="absolute inset-x-0 bottom-0 h-12 bg-gradient-to-t from-card to-transparent"/>}</div>{isLong&&<button className="mt-2 inline-flex items-center gap-1 text-[10px] font-medium text-primary" onClick={()=>setExpandedMessageIds(current=>collapsed?Array.from(new Set([...current,String(m.id)])):current.filter(id=>id!==String(m.id)))}>{collapsed?<><ChevronDown size={13}/>展开完整回答</>:<><ChevronUp size={13}/>收起回答</>}</button>}{m.role==="assistant"&&<><div className="mt-3 flex flex-wrap gap-2"><Button size="xs" variant="outline" onClick={()=>void saveNote(content)}>保存为备忘录</Button><Button size="xs" variant="outline" onClick={()=>void createExperiment(content)}>转为实验草稿</Button><Button size="xs" variant="outline" onClick={()=>void createTask(content)}>创建任务</Button><Button size="xs" variant="outline" onClick={()=>void navigator.clipboard.writeText(content).then(()=>notifyFeedback({kind:"success",title:"分析内容已复制"})).catch(()=>report(new Error("剪贴板不可用"),"复制失败"))}><Copy size={12}/>复制</Button></div>{Array.isArray(m.citations)&&(m.citations as {label:string;count:number}[]).length>0&&<p className="mt-2 text-[10px] text-muted-foreground">数据引用：{(m.citations as {label:string;count:number}[]).map(c=>`${c.label} ${c.count} 条`).join(" · ")}</p>}</>}</article>})}{sending&&<article className="max-w-[92%] rounded-2xl border border-border bg-card p-3 text-foreground md:p-4"><p className="mb-2 text-[10px] font-semibold text-muted-foreground">MoonClean Copilot · 实时生成</p><AiStreamStatus active hasText={Boolean(streamedAnswer)}/>{streamedAnswer&&<div className="mt-2"><MarkdownReply content={streamedAnswer}/></div>}</article>}</div><form onSubmit={send} className="mt-3"><Textarea value={question} onChange={e=>setQuestion(e.target.value)} maxLength={4000} rows={3} placeholder={!configured?"请先在AI 设置中连接 DeepSeek。":"输入经营问题；回答只引用当前店铺的真实数据。"} disabled={sending||mode!=="cloud"||!configured} className="resize-y rounded-2xl bg-card"/><div className="mt-2 flex items-center justify-between gap-2"><p className="text-[10px] text-muted-foreground">分析不构成自动经营操作；所有建议均需人工复核。</p><Button type="submit" disabled={sending||!question.trim()||mode!=="cloud"||!configured}>{sending?"正在读取数据并分析…":<><Send size={14}/>发送</>}</Button></div></form></SectionCard></div>{activeStoreId&&<DeepSeekUnlockDialog storeId={activeStoreId} open={pinOpen} onOpenChange={setPinOpen} onUnlock={(apiKey)=>sendWithKey(apiKey)}/>}</>;
}

export function WorkspacePage({module,initialQuestion,initialCompetitorId,initialNoteId,initialRecordId,initialConversationId}:{module:Module;initialQuestion?:string;initialCompetitorId?:string;initialNoteId?:string;initialRecordId?:string;initialConversationId?:string}){
 const {mode,activeStoreId,user}=useApp();
 const [refreshing,setRefreshing]=useState(false);
 const [cacheUpdate,setCacheUpdate]=useState<{scope:string;updatedAt:number}|null>(null);
 const cacheScope=mode==="cloud"&&activeStoreId&&user?.id?`${user.id}:${activeStoreId}`:"";
 const lastUpdated=cacheScope?(cacheUpdate?.scope===cacheScope?cacheUpdate.updatedAt:getLatestWorkspaceCacheTime(user!.id,activeStoreId!)):null;
 useEffect(()=>{
  if(!cacheScope||!activeStoreId||!user?.id)return;
  const onUpdated=(event:Event)=>{
   const detail=(event as CustomEvent<{storeId:string;userId:string;updatedAt:number}>).detail;
   if(detail?.storeId===activeStoreId&&detail.userId===user.id)setCacheUpdate({scope:cacheScope,updatedAt:detail.updatedAt});
  };
  window.addEventListener(WORKSPACE_CACHE_UPDATED_EVENT,onUpdated);
  return()=>window.removeEventListener(WORKSPACE_CACHE_UPDATED_EVENT,onUpdated);
 },[activeStoreId,cacheScope,user?.id]);
 useEffect(()=>{
  const frame=window.requestAnimationFrame(()=>{
   trackWorkspaceInteraction(module);
   pruneWorkspaceCache();
  });
  return()=>window.cancelAnimationFrame(frame);
 },[module]);
 const refresh=async()=>{setRefreshing(true);try{await refreshWorkspacePage();notifyFeedback({kind:"success",title:"云端内容已刷新",description:"当前页面的数据已重新检查。"});}catch(cause){notifyFeedback({kind:"error",title:"部分内容刷新失败",description:cause instanceof Error?cause.message:"请检查网络后重试。"});}finally{setRefreshing(false);if(cacheScope&&activeStoreId&&user?.id)setCacheUpdate({scope:cacheScope,updatedAt:getLatestWorkspaceCacheTime(user.id,activeStoreId)||Date.now()});}};
 let content:React.ReactNode;
 switch(module){
  case"notes":content=<NotesModule initialNoteId={initialNoteId}/>;break;
  case"experiments":content=<ExperimentsModule initialRecordId={initialRecordId}/>;break;
  case"competitors":content=<CompetitorsModule initialRecordId={initialRecordId}/>;break;
  case"service":content=<ServiceModule initialRecordId={initialRecordId}/>;break;
  case"copilot":content=<CopilotModule initialQuestion={initialQuestion} initialCompetitorId={initialCompetitorId} initialConversationId={initialConversationId}/>;break;
 }
 return <div onClickCapture={()=>{trackWorkspaceInteraction(module);pruneWorkspaceCache();}}>
  {mode==="cloud"&&<div className="mb-2 flex items-center justify-end gap-2 px-1 text-[10px] text-muted-foreground sm:mb-3">
   <span>{lastUpdated?`最近同步 ${new Date(lastUpdated).toLocaleTimeString("zh-CN",{hour:"2-digit",minute:"2-digit"})} · 30 秒自动检查`:"云端缓存 · 30 秒自动检查"}</span>
   <Button size="xs" variant="outline" disabled={refreshing} onClick={()=>void refresh()}><RefreshCw size={12} className={refreshing?"animate-spin":""}/>{refreshing?"刷新中":"手动刷新"}</Button>
  </div>}
  {content}
 </div>;
}
